import 'package:selective_disclosure_jwt/selective_disclosure_jwt.dart';

void main() async {
  final issuerPrivateKey = SdPrivateKey('KEY', SdJwtSignAlgorithm.es256k);
  final handler = SdJwtHandlerV1();
  final claims = {'given_name': 'Alice', 'family_name': 'Smith'};
  final disclosureFrame = {'_sd': ['given_name']};

  final sdJwt = await handler.sign(
    claims: claims,
    disclosureFrame: disclosureFrame,
    signer: SDKeySigner(issuerPrivateKey),
  );
  print(sdJwt.serialized);
}
